import { compact } from '../../util/array.js';
import { toDependency } from '../../util/input.js';
import { hasDependency } from '../../util/plugin.js';
const title = 'SWC';
const enablers = ['@swc/core'];
const isEnabled = ({ dependencies }) => hasDependency(dependencies, enablers);
const config = ['.swcrc'];
const resolveConfig = async (config) => {
    const dependencies = [];
    for (const item of [config].flat()) {
        for (const [id] of item?.jsc?.experimental?.plugins ?? [])
            dependencies.push(id);
        if (item?.jsc?.externalHelpers)
            dependencies.push('@swc/helpers');
    }
    return compact(dependencies).map(id => toDependency(id));
};
const plugin = {
    title,
    enablers,
    isEnabled,
    config,
    resolveConfig,
};
export default plugin;
